TWComponent.script:
log.info("*******************************************************************************************");
log.info("************************************ ODC PROCESS ******************************************");
log.info("*******************************************************************************************");
log.info("-------------------------------- Excetion Handling Service --------------------------------");

if (tw.system.error != undefined) {
	
	log.info("Process Instance ID: "  +tw.system.currentProcessInstanceID +" - Service Name: "+tw.local.serviceName  +" - Error: "  + String(tw.system.error.getElementByTagName("localizedMessage").item(0).getText()));
	
	var errorM = tw.local.serviceErrorMsg || String(tw.system.error.xpath("/error/message").item(0).getText());
	//var errorText = errorM.substring(errorM.indexOf(',')+1, errorM.length);
	
	tw.local.errorMSG = "Error Occured<br> Service Name : " + tw.local.serviceName + "<br> Error Type : " + String(tw.system.error.getAttribute("type")) + "<br> <br> <strong>Error Message</strong> :<br> " + errorM;
	//tw.local.errorMSG = errorM;
}else{
	tw.local.errorMSG = tw.local.serviceErrorMsg? tw.local.serviceErrorMsg : "Error occurred in service ("+tw.local.serviceName+") please contact administrator"
}



tw.local.isSuccessful = false;
log.info("*******************************************************************************************");
log.info("*******************************************************************************************");

